/**
 * The logo of one programme. A programme that is not in the list gives null:
 * the interface then shows the name only.
 */
export function logoOf(programId: string): ProgramLogo | null {
	return Object.hasOwn(PROGRAM_LOGOS, programId)
		? (PROGRAM_LOGOS[programId] ?? null)
		: null;
}
